import 'package:dmtools/src/compile/agent_pack_compiler.dart';

void probe(String label, String src) {
  final scrubbed = AgentPackCompiler.scrubForScan(src);
  final re = RegExp(r'''(?:require|loadModule)\(\s*['"]([^'"]+)['"]\s*\)''');
  final matches = re.allMatches(scrubbed).toList();
  print('=== $label');
  print('  requires found: ${matches.length}');
  print('  scrubbed: ${scrubbed.replaceAll('\n', '\\n')}');
}

void main() {
  // 1. post-increment then division (misparse candidate)
  probe('postfix ++ then division', '''
hits++ / total; var u = require('./util.js');
''');
  // 2. keyword as property name then division
  probe('obj.return division', '''
var h = obj.return / 2; var u = require('./util.js');
''');
  // 3. regex directly after closing brace (statement position)
  probe('regex after }', '''
function f() {}
/re["']/g.test(x); var u = require('./util.js');
''');
  // 4. live-shaped case: chained replaces with quote-bearing regexes (works)
  probe('chained replaces', '''
var v = String(x === null ? '' : x)
  .replace(/"/g, '\\\\\\"')
  .replace(/[<>\`|&;\$\\r\\n]/g, ' ')
  .trim();
var ms = require('./mergeState.js');
''');
  // 5. NBSP between = and a quote-bearing regex (misparse candidate)
  probe('nbsp before regex', 'var re =\u00A0/["\']/g;\nvar u = require(\'./util.js\');\n');
  // 6. length preservation + CRLF
  final crlf = 'var s = "a";\r\nvar u = require(\'./util.js\');\r\n';
  final s = AgentPackCompiler.scrubForScan(crlf);
  print('=== CRLF length preserved: ${s.length == crlf.length}');
  // 7. unterminated regex bails at EOL, next line intact
  probe('unterminated regex bail', '''
var r = x > 0 ? a / ;
var u = require('./util.js');
''');
}

