      final c = chars[i];
      if (_tryConsumeEscapePair()) continue;
      if (isTemplate && _entersInterpolation()) return;
      if (c == quote) {
        i++;
        return;
      }
      if (c == _newline && !isTemplate) return;
      _blank(i++);
    }
  }

