hits++ / total; var u = require('./util.js');
''');
  // 2. keyword as property name then division
  probe('obj.return division', '''
var h = obj.return / 2; var u = require('./util.js');
''');
  // 3. regex directly after closing brace (statement position)
  probe('regex after }', '''
function f() {}
/re["']/g.test(x); var u = require('./util.js');
''');
  // 4. live-shaped case: chained replaces with quote-bearing regexes (works)
  probe('chained replaces', '''
var v = String(x === null ? '' : x)
  .replace(/"/g, '\\\\\\"')
  .replace(/[<>\`|&;\$\\r\\n]/g, ' ')
  .trim();
var ms = require('./mergeState.js');
''');
  // 5. NBSP between = and a quote-bearing regex (misparse candidate)
