  // 6. length preservation + CRLF
  final crlf = 'var s = "a";\r\nvar u = require(\'./util.js\');\r\n';
  final s = AgentPackCompiler.scrubForScan(crlf);
  print('=== CRLF length preserved: ${s.length == crlf.length}');
  // 7. unterminated regex bails at EOL, next line intact
  probe('unterminated regex bail', '''
var r = x > 0 ? a / ;
var u = require('./util.js');
''');
}
