  /// code state.
  bool _entersInterpolation() {
    if (chars[i] != _dollar || i + 1 >= chars.length) return false;
    if (chars[i + 1] != _openBrace) return false;
    _interpBraces.add(0);
    i += 2;
    return true;
  }

