    while (i < chars.length && chars[i] != _newline) {
      _blank(i++);
    }
    return true;
  }

  bool _consumeBlockComment() {
    _blank(i++);
    _blank(i++);
    while (i < chars.length) {
      if (_atBlockCommentEnd()) {
        _blank(i++);
        _blank(i++);
        break;
      }
      if (chars[i] != _newline) _blank(i);
      i++;
